-- Minimal existing-schema fixture for isolated PGlite tests. Never production.

 create role anon; create role authenticated; create role service_role bypassrls;
 create schema auth; create schema private;
 create function auth.jwt() returns jsonb language sql as $$select coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb$$;
 create function auth.uid() returns uuid language sql as $$select (auth.jwt()->>'sub')::uuid$$;
 create table public.profiles(id uuid primary key,active boolean,role text);
 create table public.stores(id uuid primary key,subdomain text,is_active boolean,module_shipping_enabled boolean,platform_fee_enabled boolean default false,platform_fee_percent numeric default 0);
 create table public.store_users(store_id uuid,user_id uuid,active boolean);
 create table public.products(id uuid primary key default gen_random_uuid(),store_id uuid,name text,price numeric,stock integer,is_active boolean default true,combo_only boolean default false,deleted_at timestamptz);
 create table public.shipments(trip_id uuid,weight_lb numeric default 0,rate_per_lb numeric default 0,service_type_id uuid,service_type_name text,package_billing_mode text default 'weight',money_commission numeric default 0,money_commission_rate numeric default 0,money_discount numeric default 0,money_discount_reason text,customer_id uuid,sender_name text,sender_phone text,recipient_name text,recipient_phone text,recipient_address text,notes text,id text primary key,store_id uuid,tracking_code text,contains_money boolean default true,contains_package boolean default false,money_amount numeric default 0,money_total numeric default 0,weight_subtotal numeric default 0,extra_fees_total numeric default 0,discount_amount numeric default 0,amount_paid numeric default 0,service_price numeric default 0,balance_due numeric default 0,payment_status text default 'pending',status text default 'preparing',delivered boolean default false,deleted_at timestamptz);
 create function public.has_store_access(p_store_id uuid) returns boolean language sql as $$select exists(select 1 from public.profiles where id=auth.uid() and active and role='super_admin')$$;
 create function public.create_numbered_shipment(p_store_id uuid,p_id text,p_tracking_code text,p_payload jsonb) returns jsonb language plpgsql as $$declare s public.shipments;begin insert into public.shipments(id,store_id,tracking_code,contains_package,contains_money,money_amount,money_total,amount_paid) values(p_id,p_store_id,p_tracking_code,coalesce((p_payload->>'contains_package')::boolean,false),coalesce((p_payload->>'contains_money')::boolean,true),(p_payload->>'money_amount')::numeric,(p_payload->>'money_total')::numeric,coalesce((p_payload->>'amount_paid')::numeric,0)) returning * into s;return to_jsonb(s);end$$;

 create table public.orders(id uuid primary key default gen_random_uuid(),store_id uuid not null,order_number text,customer_id uuid,customer_name text,customer_phone text,recipient_name text,recipient_phone text,address text not null,exact_address text,country text,notes text,total numeric not null,subtotal numeric default 0,discount_amount numeric default 0,delivery_fee numeric default 0,platform_fee_amount numeric not null default 0,platform_fixed_fee_amount numeric not null default 0.30,status text default 'pending',payment_status text default 'pending',payment_method text default 'whatsapp',stock_restored boolean default false,deleted_at timestamptz,created_at timestamptz default now());
 create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid references public.orders(id),product_id uuid references public.products(id),product_name text not null,item_type text default 'product',quantity integer not null,price numeric not null,base_price numeric,platform_fee_amount numeric not null default 0,subtotal numeric not null);
